import { parseInstant } from '@absoluteui/core';
import { SchedulePicker, scheduleToString, type SchedulePickerChangeDetail } from '@absoluteui/components/schedule-picker';

const start = parseInstant('2026-09-29T08:00:00Z');
const end = parseInstant('2026-09-29T09:00:00Z');
const host = document.createElement('div');
document.body.append(host);
if (start && end) {
  SchedulePicker.create(host, {
    label: 'When',
    name: 'when',
    value: { allDay: false, start, end, timeZone: 'Europe/London', recurrence: null },
    timeZones: ['Europe/London', 'America/New_York', 'Asia/Kolkata'],
    recurrence: true,
  });
}
host.addEventListener('aui-change', (event) => {
  const { value } = (event as CustomEvent<SchedulePickerChangeDetail>).detail;
  host.dataset.ical = value ? scheduleToString(value) : '';
});

import { parseSchedule, SchedulePicker } from '@absoluteui/components/schedule-picker';

const saved = 'DTSTART;VALUE=DATE:20261224\nDTEND;VALUE=DATE:20261227';
const host = document.createElement('div');
document.body.append(host);
const picker = SchedulePicker.create(host, { label: 'Office closed', value: parseSchedule(saved), required: true });
export const text = picker.getFormValue();
